public class GUPDiscountClaimProcessDialog extends RunBaseBatch implements BatchRetryable
{
    QueryRun queryRun;

    #DEFINE.CurrentVersion(1)

}

Method.Source:
public void initQueryRun()
{
    queryRun = new QueryRun(queryStr(GUPDiscountClaim));
}

public void run()
{
    while (queryRun.next())
    {
        GUPDiscountClaim discountClaim = queryRun.get(tableNum(GUPDiscountClaim));
        GUPDiscountClaimProcess discountClaimProcess = new GUPDiscountClaimProcess();

        setPrefix(strFmt("@GlobalUnifiedPricing:DiscountClaimPrefix", discountClaim.DiscountClaimId));
        discountClaimProcess.process(discountClaim);
    }
}

public boolean unpack(container _packedClass)
{
    Integer     version = conpeek(_packedClass,1);
    boolean     ret = true;
    container   packedQuery;

    switch (version)
    {
        case #CurrentVersion:
            [version, packedQuery] = _packedClass;
            if (packedQuery)
            {
                queryRun = new QueryRun(packedQuery);
            }
            break;
        default:
            ret = false;
            break;
    }

    return ret;
}

public static GUPDiscountClaimProcessDialog construct()
{
    return new GUPDiscountClaimProcessDialog();
}

public static void main(Args _args)
{
    GUPDiscountClaimProcessDialog gupDiscountClaimProcessDialog = GUPDiscountClaimProcessDialog::construct();

    try
    {
        if (gupDiscountClaimProcessDialog.prompt())
        {
            gupDiscountClaimProcessDialog.runOperation();

            Common record = _args.record();
            if (record && FormDataUtil::getFormDataSource(record))
            {
                FormDataSource dataSource = FormDataUtil::getFormDataSource(record);
                dataSource.research();
            }
        }
    }
    catch (Exception::Error)
    {
        throw error("@SYS4081590");
    }
}
